UPDATE "Translation" SET "ru" = 'Дорогие друзья! Стрельба из лука — это не просто спорт, это наследие Великой степи, живущее в крови нашего народа. Мы гордимся нашими историческими корнями и современными достижениями наших атлетов на мировой арене. Наша цель — сделать стрельбу из лука массовым и доступным спортом, воспитывая новое поколение чемпионов, которые с честью поднимут флаг Казахстана на олимпийских пьедесталах. Вместе мы попадём точно в цель!', "updatedAt" = CURRENT_TIMESTAMP WHERE "namespace" = 'LeadershipPage' AND "key" = 'president_quote' AND "ru" IS NOT DISTINCT FROM 'Дорогие друзья! Стрельба из лука — это не просто спорт, это наследие Великой Степи, живущее в крови нашего народа. Мы гордимся нашими историческими корнями и современными достижениями наших атлетов на мировой арене. Наша цель — сделать стрельбу из лука массовым и доступным спортом, воспитывая новое поколение чемпионов, которые с честью поднимут флаг Казахстана на Олимпийских пьедесталах. Вместе мы попадем точно в цель!';
