UPDATE "SiteContent" SET "value" = 'Наша миссия — формирование здоровой и сильной нации через развитие массового спорта и воспитание чемпионов мирового уровня. Мы стремимся сделать стрельбу из лука самым доступным и популярным видом спорта в Казахстане, создавая условия для раскрытия потенциала каждого атлета — от школьного стадиона до олимпийского пьедестала.', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'mission_desc' AND "value" IS NOT DISTINCT FROM 'Наша миссия — формирование здоровой и сильной нации через развитие массового спорта и воспитание чемпионов мирового уровня. Мы стремимся сделать стрельбу из лука самым доступным и популярным видом спорта в Казахстане, создавая условия для раскрытия потенциала каждого атлета — от школьного стадиона до Олимпийского пьедестала.';
UPDATE "SiteContent" SET "valueEn" = 'Our mission is to build a healthy and strong nation by developing grassroots sport and nurturing world-class champions. We strive to make archery the most accessible and popular sport in Kazakhstan by creating conditions for every athlete to realize their potential — from the school sports ground to the Olympic podium.', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'mission_desc' AND "valueEn" IS NOT DISTINCT FROM 'Our mission is to build a healthy and strong nation through developing mass sports and nurturing world-class champions. We strive to make archery the most accessible and popular sport in Kazakhstan.';
UPDATE "SiteContent" SET "valueKk" = 'Біздің миссиямыз — бұқаралық спортты дамыту және әлемдік деңгейдегі чемпиондарды дайындау арқылы дені сау әрі мықты ұлтты қалыптастыру. Біз мектеп стадионынан олимпиадалық тұғырға дейін әрбір спортшының әлеуетін ашуға жағдай жасай отырып, садақ атуды Қазақстандағы ең қолжетімді әрі танымал спорт түріне айналдыруға ұмтыламыз.', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'mission_desc' AND "valueKk" IS NOT DISTINCT FROM 'Біздің миссиямыз — бұқаралық спортты дамыту және әлемдік деңгейдегі чемпиондарды дайындау арқылы сау және күшті ұлтты қалыптастыру. Біз садақ атуды Қазақстандағы ең қолжетімді және танымал спорт түріне айналдыруға ұмтыламыз.';
UPDATE "SiteContent" SET "valueEn" = 'Building a Healthy and Strong Nation', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'mission_title' AND "valueEn" IS NOT DISTINCT FROM 'Building a healthy and strong nation';
UPDATE "SiteContent" SET "value" = 'Федерация является полноправным членом World Archery и World Archery Asia. Мы соблюдаем высочайшие стандарты честной игры, антидопинговой политики и спортивной этики.', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'recognition_desc' AND "value" IS NOT DISTINCT FROM 'Федерация является полноправным членом World Archery и Asian Archery Federation. Мы соблюдаем высочайшие стандарты честной игры, антидопинговой политики и спортивной этики.';
UPDATE "SiteContent" SET "valueEn" = 'The Federation is a full member of World Archery and World Archery Asia. We uphold the highest standards of fair play, anti-doping policy and sports ethics.', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'recognition_desc' AND "valueEn" IS NOT DISTINCT FROM 'The Federation is a full member of World Archery and Asian Archery Federation. We uphold the highest standards of fair play, anti-doping policy, and sports ethics.';
UPDATE "SiteContent" SET "valueKk" = 'Федерация World Archery және World Archery Asia ұйымдарының толыққанды мүшесі болып табылады. Біз әділ ойын, допингке қарсы саясат және спорттық этиканың ең жоғары стандарттарын сақтаймыз.', "updatedAt" = CURRENT_TIMESTAMP WHERE "key" = 'recognition_desc' AND "valueKk" IS NOT DISTINCT FROM 'Федерация World Archery және Asian Archery Federation толыққанды мүшесі болып табылады. Біз әділ ойын, допингке қарсы саясат және спорттық этиканың ең жоғары стандарттарын сақтаймыз.';
