UPDATE "Staff" SET "description" = 'Стрельба из лука — это древнее искусство, которое объединяет точность, концентрацию и дисциплину. Мы стремимся развивать этот вид спорта, сохраняя традиции наших предков и внедряя современные методики подготовки.', "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = 1 AND "description" IS NOT DISTINCT FROM 'Стрельба из лука – это древнее искусство, которое объединяет точность, концентрацию и дисциплину. Мы стремимся развивать этот вид спорта, сохраняя традиции наших предков и внедряя современные методики подготовки.';
UPDATE "Staff" SET "descriptionKk" = 'Садақ ату — дәлдікті, зейінді және тәртіпті біріктіретін ежелгі өнер. Біз бабаларымыздың дәстүрін сақтай отырып және заманауи даярлық әдістемелерін енгізе отырып, осы спорт түрін дамытуға ұмтыламыз.', "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = 1 AND "descriptionKk" IS NOT DISTINCT FROM 'Садақ ату - дәлдік, шоғырлану және тәртіпті біріктіретін ежелгі өнер. Біз бабаларымыздың дәстүрлерін сақтай отырып және заманауи даярлау әдістемелерін енгізе отырып, бұл спорт түрін дамытуға тырысамыз.';
