UPDATE "HistoryEvent" SET "descriptionKk" = 'Қазақстан аумағында садақ пен жебенің қолданылғаны туралы алғашқы деректер қола дәуіріне жатады. Біздің бабаларымыз шебер садақшылар болған.', "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = 1 AND "descriptionKk" IS NOT DISTINCT FROM 'Қазақстан территориясында садақ пен жебені пайдаланудың алғашқы дәлелдері қола дәуірінен басталады. Біздің бабаларымыз шебер садақшылар болған.';
